        self.val = val
        self.next = next
        self.random = random


def build_random(rows):
    nodes = [Node(v) for v, _ in rows]
    for i, (_, r) in enumerate(rows):
        if i + 1 < len(nodes):
            nodes[i].next = nodes[i + 1]
        if r != -1:
            nodes[i].random = nodes[r]
    return nodes[0] if nodes else None


def dump_random(head):
    idx = {}
    cur, i = head, 0
